#include <stdlib.h>
#include <string.h>
int main(void){
    FILE *f=fopen("/app/data.txt","rb");
    static unsigned char d[100000]; int n=0,c;
    while((c=fgetc(f))!=EOF) d[n++]=c;
    /* all repeated substrings len>=8: for each len L, count occurrences of each L-gram */
    for (int L=8; L<=120; L+=4) {
        /* count pairs (i<j, d[i..i+L]==d[j..j+L]), report total bytes covered by pairs with maxL match >= L */
        long pairs=0, bestlen_sum=0;
        for (int i=0; i+L<=n; i++) {
            for (int j=i+1; j+L<=n; j++) {
                int m=0;
                while (m<L+2000 && d[i+m]==d[j+m]) m++;
                if (m>=L) { pairs++; bestlen_sum+=m; }
            }
        }
        if (pairs) printf("L=%d pairs=%ld totalmatchlen=%ld\n", L, pairs, bestlen_sum);
    }
    return 0;
}
